import { useQuery } from "@apollo/client";
import { Card, Col, Flex, Image, Row, Skeleton, Space, Typography } from "antd";
import query_scGetDetailOrder from "graphql/queries/query_scGetDetailOrder";
import React, { Fragment, memo, useEffect, useMemo, useState } from "react";
import styled from "styled-components";
import { formatNumberToCurrency, renderStatusName } from "utils/helper";

const OrderMessageWrapper = styled.div`
    .ant-card-head {
        min-height: unset;
        padding: 8px 16px;
    }

    .ant-card-body {        
        padding: 8px 16px;
    }

    .ant-card-bordered {
        border: none;
    }

    .ant-card-head-title {
        font-size: 15px;
    }

    .image-product {
        object-fit: contain;
        border-radius: 8px;

        &.ant-skeleton-image {
            width: 100%;
            height: 50px;
        }
    }

    .order-body {
        width: 350px;
    }
`;

const { Text } = Typography;

const OrderMessage = ({ order }) => {
    const { loading: loadingOrderDetail, data: dataOrderDetail } = useQuery(query_scGetDetailOrder, {
        variables: {
            ref_id: String(order?.[0]?.info?.order_id)
        },
        fetchPolicy: 'cache-and-network'
    });

    const [imageOrder] = useMemo(() => {
        return [dataOrderDetail?.findOrderDetail?.orderItems?.[0]?.variant_image || ''];
    }, [dataOrderDetail]);

    return <OrderMessageWrapper>
        <Card title="Đơn hàng">
            <Row gutter={20} className={loadingOrderDetail ? "order-body" : ""}>
                <Col span={5}>
                    {loadingOrderDetail && <Skeleton.Image className="image-product" active />}
                    {!loadingOrderDetail && <Image
                        className="image-product"
                        preview={false}
                        src={imageOrder}
                        fallback={!imageOrder ? "data:image/png;base64," : ""}
                    />}
                </Col>
                <Col span={19} className="order-right">
                    {loadingOrderDetail && <Skeleton title={false} paragraph active />}
                    {!loadingOrderDetail && <Fragment>
                        <Flex vertical gap={2}>
                            <Text>Mã đơn hàng: <Text style={{ fontWeight: 'bold' }} copyable>{dataOrderDetail?.findOrderDetail?.ref_id}</Text></Text>
                            <Text>Tổng đơn hàng: <Text strong>{formatNumberToCurrency(dataOrderDetail?.findOrderDetail?.paid_price)}đ</Text></Text>
                        </Flex>
                        <Text type={dataOrderDetail?.findOrderDetail?.status == 'COMPLETED' ? "success" : "danger"} strong>
                            {!!dataOrderDetail?.findOrderDetail?.returnOrder
                                ? <Space align="center">
                                    <Text type="secondary">Hoàn thành</Text>
                                    <Text type="danger">{` -> Đơn hoàn`}</Text>
                                </Space>
                                : renderStatusName(dataOrderDetail?.findOrderDetail)?.status}
                        </Text>
                    </Fragment>}
                </Col>
            </Row>
        </Card>
    </OrderMessageWrapper>
};

export default memo(OrderMessage);